 try{cc_rate_limit('password:'.$uid,5,3600);verify_csrf($_POST['csrf']??null);$current=(string)($_POST['current_password']??'');$next=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');if($next!==$confirm)throw new RuntimeException('Новые пароли не совпадают.');if(mb_strlen($next)<10||mb_strlen($next)>128||!preg_match('/\p{L}/u',$next)||!preg_match('/\d/u',$next))throw new RuntimeException('Новый пароль: 10–128 символов, минимум одна буква и одна цифра.');$q=db()->prepare('SELECT password_hash FROM users WHERE id=? LIMIT 1');$q->execute([$uid]);$hash=$q->fetchColumn();if(!$hash||!password_verify($current,(string)$hash))throw new RuntimeException('Текущий пароль указан неверно.');db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($next,PASSWORD_DEFAULT),$uid]);session_regenerate_id(true);$_SESSION=['user_id'=>$uid,'csrf'=>bin2hex(random_bytes(24))];$notice='Пароль обновлён.';}catch(RuntimeException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->__toString());$error='Не удалось обновить пароль.';}
